1	// Admin shell: AppBar + top TabBar around admin pages.
2	// Spec: docs/09-page-flow-design.md §3 (admin shell).
3	//
4	// Top tabs: Requests · Drones · Control · More.
5	// The "More" tab opens a bottom sheet exposing Weather / Inventory / Profile,
6	// matching the design's secondary-nav drawer behaviour.
7	
8	import 'package:flutter/material.dart';
9	import 'package:flutter_riverpod/flutter_riverpod.dart';
10	import 'package:go_router/go_router.dart';
11	
12	import '../widgets/notification_bell.dart';
13	import '../widgets/weather_chip.dart';
14	
15	class AdminShell extends ConsumerStatefulWidget {
16	  const AdminShell({super.key, required this.child});
17	
18	  final Widget child;
19	
20	  @override
21	  ConsumerState<AdminShell> createState() => _AdminShellState();
22	}
23	
24	class _AdminShellState extends ConsumerState<AdminShell>
25	    with SingleTickerProviderStateMixin {
26	  static const _tabs = <_AdminTabSpec>[
27	    _AdminTabSpec(route: '/admin/requests', label: 'Requests', icon: Icons.assignment),
28	    _AdminTabSpec(route: '/admin/reports',  label: 'Reports',  icon: Icons.report_outlined),
29	    _AdminTabSpec(route: '/admin/drones',   label: 'Drones',   icon: Icons.flight),
30	    _AdminTabSpec(route: '/admin/control',  label: 'Control',  icon: Icons.map),
31	  ];
32	
33	  late final TabController _controller;
34	
35	  /// True while a programmatic `animateTo` is running (deep-link sync,
36	  /// More-sheet fallback). The TabController listener fires on every
37	  /// index change — user-tapped AND programmatic — and we only want
38	  /// the user-tap branch to navigate. Without this guard, navigating
39	  /// to a non-primary route (e.g. /admin/weather, /admin/notifications)
40	  /// would trigger the sync animateTo, which would re-fire the listener
41	  /// and `context.go` back to the primary fallback tab (Requests).
42	  bool _syncing = false;
43	
44	  @override
45	  void initState() {
46	    super.initState();
47	    // 5 tabs total: 4 primary destinations + "More" sheet trigger.
48	    _controller = TabController(length: _tabs.length + 1, vsync: this);
49	    _controller.addListener(_onTabSelected);
50	  }
51	
52	  @override
53	  void dispose() {
54	    _controller.removeListener(_onTabSelected);
55	    _controller.dispose();
56	    super.dispose();
57	  }
58	
59	  void _onTabSelected() {
60	    if (!_controller.indexIsChanging) return;
61	    if (_syncing) {
62	      _syncing = false;
63	      return;
64	    }
65	    final i = _controller.index;
66	    if (i == _tabs.length) {
67	      // "More" — pop sheet, snap selection back to the active primary tab.
68	      _showMoreSheet();
69	      final fallback = _primaryIndexFor(GoRouterState.of(context).matchedLocation);
70	      _syncing = true;
71	      _controller.animateTo(fallback);
72	      return;
73	    }
74	    final route = _tabs[i].route;
75	    if (GoRouterState.of(context).matchedLocation != route) {
76	      context.go(route);
77	    }
78	  }
79	
80	  int _primaryIndexFor(String location) {
81	    for (var i = 0; i < _tabs.length; i++) {
82	      if (location.startsWith(_tabs[i].route)) return i;
83	    }
84	    return 0;
85	  }
86	
87	  @override
88	  Widget build(BuildContext context) {
89	    final location = GoRouterState.of(context).matchedLocation;
90	    final primaryIndex = _primaryIndexFor(location);
91	    if (_controller.index != primaryIndex &&
92	        !_controller.indexIsChanging) {
93	      // Sync underline to the currently active route (e.g. after deep link).
94	      WidgetsBinding.instance.addPostFrameCallback((_) {
95	        if (!mounted) return;
96	        _syncing = true;
97	        _controller.animateTo(primaryIndex);
98	      });
99	    }
100	
101	    return Scaffold(
102	      appBar: AppBar(
103	        title: const Text('DroneAid · Admin'),
104	        actions: [
105	          const WeatherChip(),
106	          const NotificationBell(),
107	          IconButton(
108	            tooltip: 'Weather settings',
109	            onPressed: () => context.go('/admin/weather'),
110	            icon: const Icon(Icons.settings_outlined),
111	          ),
112	          const SizedBox(width: 4),
113	        ],
114	        bottom: TabBar(
115	          controller: _controller,
116	          isScrollable: true,
117	          tabAlignment: TabAlignment.start,
118	          tabs: [
119	            for (final t in _tabs)
120	              Tab(icon: Icon(t.icon), text: t.label),
121	            const Tab(icon: Icon(Icons.more_horiz), text: 'More'),
122	          ],
123	        ),
124	      ),
125	      body: widget.child,
126	    );
127	  }
128	
129	  Future<void> _showMoreSheet() async {
130	    await showModalBottomSheet<void>(
131	      context: context,
132	      showDragHandle: true,
133	      builder: (ctx) {
134	        return SafeArea(
135	          child: Column(
136	            mainAxisSize: MainAxisSize.min,
137	            children: [
138	              ListTile(
139	                leading: const Icon(Icons.cloud_outlined),
140	                title: const Text('Weather'),
141	                onTap: () {
142	                  Navigator.of(ctx).pop();
143	                  context.go('/admin/weather');
144	                },
145	              ),
146	              ListTile(
147	                leading: const Icon(Icons.inventory_2_outlined),
148	                title: const Text('Inventory'),
149	                onTap: () {
150	                  Navigator.of(ctx).pop();
151	                  context.go('/admin/inventory');
152	                },
153	              ),
154	              ListTile(
155	                leading: const Icon(Icons.person_outline),
156	                title: const Text('Profile'),
157	                onTap: () {
158	                  Navigator.of(ctx).pop();
159	                  context.go('/admin/profile');
160	                },
161	              ),
162	              const SizedBox(height: 8),
163	            ],
164	          ),
165	        );
166	      },
167	    );
168	  }
169	}
170	
171	class _AdminTabSpec {
172	  const _AdminTabSpec({
173	    required this.route,
174	    required this.label,
175	    required this.icon,
176	  });
177	  final String route;
178	  final String label;
179	  final IconData icon;
180	}
