        color: muted,
      ),
      metricValue: const TextStyle(
        fontSize: 16,
        fontWeight: FontWeight.w700,
        color: Color(0xFF1F2937),
      ),
    );
  }

  static AppTextStyles dark(ColorScheme s) {
    final muted = const Color(0xFFA0A8B4);
    return AppTextStyles(
      eyebrow: TextStyle(
        fontSize: 11,
        fontWeight: FontWeight.w600,
        letterSpacing: 1.4,
        color: muted,
        fontFamily: _monoFamily,
      ),
      sectionLabel: TextStyle(
        fontSize: 12,
        fontWeight: FontWeight.w600,
        letterSpacing: 1.0,
        color: muted,
      ),
      mono: TextStyle(
        fontSize: 13,
        fontFamily: _monoFamily,
        color: muted,
        height: 1.3,
      ),
      monoStrong: TextStyle(
        fontSize: 13,
        fontFamily: _monoFamily,
        fontWeight: FontWeight.w600,
        color: const Color(0xFFE6EAF0),
        height: 1.3,
      ),
      requestId: TextStyle(
        fontSize: 13,
        fontFamily: _monoFamily,
        color: s.primary,
        fontWeight: FontWeight.w500,
      ),
      metricLabel: TextStyle(
        fontSize: 11,
        fontWeight: FontWeight.w600,
