                ),
              ),
            ),
          Text(
            _labelFor(status),
            style: TextStyle(
              color: style.fg,
              fontSize: dense ? 11 : 12,
              fontWeight: FontWeight.w700,
              letterSpacing: style.allCaps ? 0.5 : 0.1,
            ),
          ),
        ],
      ),
    );
  }

  static String _labelFor(String status) {
    switch (status) {
      case 'in_flight':
      case 'enroute':
        return 'In flight';
      case 'delivering':
        return 'Delivering';
      case 'returning':
        return 'Returning';
      case 'pending':
        return 'Pending';
      case 'approved':
        return 'Approved';
      case 'assigned':
        return 'Assigned';
      case 'delivered':
        return 'Delivered';
      case 'confirmed':
        return 'Confirmed';
      case 'completed':
        return 'Completed';
      case 'rejected':
        return 'Rejected';
      case 'aborted':
        return 'Aborted';
      case 'failed':
        return 'Failed';
      case 'cancelled':
        return 'Cancelled';
      case 'urgent':
        return 'URGENT';
      default:
        return status.replaceAll('_', ' ');
    }
  }
}

class _StatusStyle {
  const _StatusStyle({
    required this.bg,
    required this.fg,
    required this.dot,
    this.allCaps = false,
  });
  final Color bg;
  final Color fg;
  final bool dot;
  final bool allCaps;

  factory _StatusStyle.forStatus(String status, AppStatusColors p) {
    switch (status) {
      case 'pending':
        return _StatusStyle(bg: p.pendingBg, fg: p.pendingFg, dot: true);
      case 'approved':
      case 'assigned':
        return _StatusStyle(bg: p.approvedBg, fg: p.approvedFg, dot: true);
      case 'in_flight':
      case 'enroute':
      case 'delivering':
      case 'returning':
        return _StatusStyle(bg: p.inFlightBg, fg: p.inFlightFg, dot: true);
      case 'delivered':
        return _StatusStyle(bg: p.deliveredBg, fg: p.deliveredFg, dot: true);
      case 'confirmed':
      case 'completed':
        return _StatusStyle(bg: p.confirmedBg, fg: p.confirmedFg, dot: true);
      case 'failed':
      case 'aborted':
        return _StatusStyle(bg: p.failedBg, fg: p.failedFg, dot: true);
      case 'rejected':
        return _StatusStyle(bg: p.failedBg, fg: p.failedFg, dot: true);
      case 'cancelled':
        return _StatusStyle(bg: p.cancelledBg, fg: p.cancelledFg, dot: true);
      case 'urgent':
      case 'URGENT':
        return _StatusStyle(
          bg: p.urgentBg,
          fg: p.urgentFg,
          dot: false,
          allCaps: true,
        );
      default:
        return _StatusStyle(bg: p.cancelledBg, fg: p.cancelledFg, dot: true);
    }
  }
}

