24	    final catalogAsync = ref.watch(activeCatalogProvider);
25	    final cart = ref.watch(cartProvider);
26	    final profile = ref.watch(userProfileProvider).valueOrNull;
27	
28	    // Seed the pin from the user's profile delivery address the first time
29	    // the catalog page renders with a non-null profile.
30	    if (cart.pin == null && profile?.deliveryAddress != null) {
31	      final addr = profile!.deliveryAddress!;
