39	              );
40	        });
41	      }
42	    }
43	
44	    return Scaffold(
45	      body: catalogAsync.when(
46	        loading: () => const LoadingPlaceholder(label: 'Loading supplies…'),
47	        error: (e, _) => Center(child: Text('Failed to load catalog: $e')),
48	        data: (catalog) {
49	          if (catalog.isEmpty) {
50	            return const Center(
51	              child: Padding(
