53	                child: Text(
54	                  'No supplies available right now. Check back soon.',
55	                  textAlign: TextAlign.center,
56	                ),
57	              ),
58	            );
59	          }
60	          final totalKg = cartTotalWeightKg(cart, catalog);
61	          return ListView(
62	            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
63	            children: [
64	              Text(
65	                'Pick what you need, drop a pin.',
66	                style: Theme.of(context).textTheme.bodyMedium,
67	              ),
