12	import 'package:cloud_firestore/cloud_firestore.dart';
13	
14	/// Section buckets shown on P-U-04. `hidden` items live in P-U-07 History.
15	enum QueueBucket { pending, active, hidden }
16	
17	class RequestItemLine {
18	  const RequestItemLine({required this.catalogId, required this.qty});
19	  final String catalogId;
20	  final int qty;
21	}
22	
23	class AppRequest {
24	  const AppRequest({
25	    required this.id,
26	    required this.userId,
27	    required this.status,
28	    required this.items,
29	    required this.totalWeightKg,
30	    required this.createdAt,
31	    this.currentFlightId,
32	  });
33	
34	  final String id;
35	  final String userId;
36	  final String status;
37	  final List<RequestItemLine> items;
38	  final double totalWeightKg;
39	  final DateTime? createdAt;
40	  final String? currentFlightId;
41	
42	  factory AppRequest.fromSnap(
43	    QueryDocumentSnapshot<Map<String, dynamic>> snap,
44	  ) {
45	    final data = snap.data();
46	    final rawItems = (data['items'] as List?) ?? const [];
47	    final items = rawItems
48	        .whereType<Map<String, dynamic>>()
49	        .map(
50	          (m) => RequestItemLine(
51	            catalogId: (m['catalogId'] as String?) ?? '',
52	            qty: (m['qty'] as num?)?.toInt() ?? 0,
53	          ),
54	        )
55	        .toList(growable: false);
56	    return AppRequest(
57	      id: snap.id,
58	      userId: (data['userId'] as String?) ?? '',
59	      status: (data['status'] as String?) ?? 'pending',
60	      items: items,
61	      totalWeightKg: (data['totalWeightKg'] as num?)?.toDouble() ?? 0,
62	      createdAt: (data['createdAt'] as Timestamp?)?.toDate(),
63	      currentFlightId: data['currentFlightId'] as String?,
64	    );
65	  }
66	
67	  QueueBucket get bucket => bucketFor(status);
68	}
69	
70	/// Pure helper — maps a status string to the P-U-04 section bucket.
71	/// See spec §5 P-U-04 "Sections".
72	QueueBucket bucketFor(String status) {
73	  switch (status) {
74	    case 'pending':
75	      return QueueBucket.pending;
76	    case 'approved':
77	    case 'assigned':
78	    case 'in_flight':
79	    case 'delivered':
80	      return QueueBucket.active;
81	    default:
82	      // rejected, cancelled, failed, aborted, confirmed, completed → History.
83	      return QueueBucket.hidden;
84	  }
85	}
86	
87	/// Pure helper — turns request items into "Food Kit ×2 · Blanket ×1".
88	/// Falls back to the raw catalogId when a name is unknown.
89	String formatItemSummary(
90	  List<RequestItemLine> items,
91	  Map<String, String> catalogNames,
92	) {
93	  if (items.isEmpty) return '(no items)';
94	  return items
95	      .map((it) => '${catalogNames[it.catalogId] ?? it.catalogId} ×${it.qty}')
96	      .join(' · ');
97	}
98	
99	/// Pure helper — human-friendly relative time like "Just now", "7 min ago",
100	/// "3 h ago", "Yesterday", "Mar 14". Pure for testability.
101	String relativeTime(DateTime? when, {DateTime? now}) {
102	  if (when == null) return '—';
103	  final ref = now ?? DateTime.now();
104	  final diff = ref.difference(when);
105	  if (diff.isNegative) return 'Just now';
106	  if (diff.inSeconds < 60) return 'Just now';
107	  if (diff.inMinutes < 60) return '${diff.inMinutes} min ago';
108	  if (diff.inHours < 24) return '${diff.inHours} h ago';
109	  if (diff.inDays == 1) return 'Yesterday';
110	  if (diff.inDays < 7) return '${diff.inDays} d ago';
111	  // Older than a week — drop to a calendar date. Kept locale-naive on
112	  // purpose; intl formatting can be layered on later without breaking tests.
113	  const months = [
114	    'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
115	    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
116	  ];
117	  return '${months[when.month - 1]} ${when.day}';
118	}
