    void toggle(String? s) {
      final next = {...selected};
      if (s == null) {
        next.clear();
      } else if (!next.add(s)) {
        next.remove(s);
      }
      ref.read(_droneFilterProvider.notifier).state = next;
    }

    Widget chip({
      required Key key,
