// P-U-01 Log in.
// Layout + behaviour mirror docs/10-prototype-design.md §P-U-01.

import 'package:firebase_auth/firebase_auth.dart';
import 'package:firebase_crashlytics/firebase_crashlytics.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../core/auth/auth_providers.dart';
import '../../core/dev_mode.dart';
import '../../utils/thai_id_validator.dart';

class LoginPage extends ConsumerStatefulWidget {
  const LoginPage({super.key});

  @override
  ConsumerState<LoginPage> createState() => _LoginPageState();
}

class _LoginPageState extends ConsumerState<LoginPage> {
  final _formKey = GlobalKey<FormState>();
  final _idCtrl = TextEditingController();
  final _pwCtrl = TextEditingController();
  bool _obscure = true;
  bool _submitting = false;
  String? _serverError;

  @override
  void dispose() {
    _idCtrl.dispose();
    _pwCtrl.dispose();
    super.dispose();
  }

  String? _validateNationalId(String? v) {
    final s = (v ?? '').trim();
    if (s.isEmpty) return 'Required';
    if (s.length != 13) return 'Must be 13 digits';
    if (!ThaiIdValidator.isValid(s)) return 'Invalid national ID';
    return null;
  }

  String? _validatePassword(String? v) {
    final s = v ?? '';
    if (s.isEmpty) return 'Required';
    if (s.length < 8) return 'At least 8 characters';
    return null;
  }

  Future<void> _submit() async {
    setState(() => _serverError = null);
    if (!_formKey.currentState!.validate()) return;
    setState(() => _submitting = true);
    try {
      await ref.read(authRepositoryProvider).signInWithNationalId(
            nationalId: _idCtrl.text.trim(),
            password: _pwCtrl.text,
          );
      // Router redirect carries us to /user/home or /admin/requests.
    } on FirebaseAuthException catch (_) {
      setState(() => _serverError = 'Wrong national ID or password.');
    } catch (_) {
      setState(() => _serverError = 'Could not reach the server. Try again.');
    } finally {
      if (mounted) setState(() => _submitting = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Scaffold(
      body: SafeArea(
        child: Form(
          key: _formKey,
          autovalidateMode: AutovalidateMode.onUserInteraction,
          child: ListView(
            padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 32),
            children: [
              Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                Icon(
                  Icons.flight_takeoff,
                  size: 56,
                  color: theme.colorScheme.primary,
                ),
                const SizedBox(height: 16),
                Text(
                  'DroneAid',
                  textAlign: TextAlign.center,
                  style: theme.textTheme.headlineMedium
                      ?.copyWith(fontWeight: FontWeight.bold),
                ),
                const SizedBox(height: 4),
                Text(
                  'Relief delivery, on demand.',
                  textAlign: TextAlign.center,
                  style: theme.textTheme.bodyMedium,
                ),
                const SizedBox(height: 32),
                TextFormField(
                  controller: _idCtrl,
                  keyboardType: TextInputType.number,
                  inputFormatters: [
                    FilteringTextInputFormatter.digitsOnly,
                    LengthLimitingTextInputFormatter(13),
                  ],
                  decoration: const InputDecoration(
                    labelText: '13-digit national ID',
                    counterText: '',
                    border: OutlineInputBorder(),
                  ),
                  validator: _validateNationalId,
                  textInputAction: TextInputAction.next,
                ),
                const SizedBox(height: 12),
                TextFormField(
                  controller: _pwCtrl,
                  obscureText: _obscure,
                  decoration: InputDecoration(
                    labelText: 'Password',
                    border: const OutlineInputBorder(),
                    suffixIcon: IconButton(
                      icon: Icon(_obscure ? Icons.visibility : Icons.visibility_off),
                      onPressed: () => setState(() => _obscure = !_obscure),
                    ),
                  ),
                  validator: _validatePassword,
                  textInputAction: TextInputAction.done,
                  onFieldSubmitted: (_) => _submit(),
                ),
                if (_serverError != null) ...[
                  const SizedBox(height: 12),
                  Text(
                    _serverError!,
                    style: TextStyle(color: theme.colorScheme.error),
                  ),
                ],
                const SizedBox(height: 24),
                FilledButton(
                  onPressed: _submitting ? null : _submit,
                  child: _submitting
                      ? const SizedBox(
                          width: 18, height: 18,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        )
                      : const Text('Log in'),
                ),
                const SizedBox(height: 12),
                TextButton(
                  onPressed: _submitting ? null : () => context.push('/register'),
                  child: const Text('New here?  Create an account →'),
                ),
                const SizedBox(height: 32),
                if (kShowDevSurfaces) ...[
                  const _DemoAccountsCard(),
                  const SizedBox(height: 12),
                  const _CrashTestCard(),
                ],
              ],
            ),
            ],
          ),
        ),
      ),
    );
  }
}

class _DemoAccountsCard extends StatelessWidget {
  const _DemoAccountsCard();

  @override
  Widget build(BuildContext context) {
    return const Card(
      margin: EdgeInsets.zero,
      child: Padding(
        padding: EdgeInsets.all(12),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'Demo accounts',
              style: TextStyle(fontWeight: FontWeight.bold),
            ),
            SizedBox(height: 4),
            Text(
              'Mali (user)   [REDACTED:thai-id] · Demo#101',
              style: TextStyle(fontFamily: 'monospace', fontSize: 12),
            ),
            Text(
              'Admin         [REDACTED:thai-id] · Admin#001',
              style: TextStyle(fontFamily: 'monospace', fontSize: 12),
            ),
          ],
        ),
      ),
    );
  }
}

/// Crashlytics test surface.
///
/// Crashlytics collection is disabled in debug unless you run with:
///   flutter run --dart-define=FORCE_CRASHLYTICS=true
/// (or use a release build). Without that flag, the buttons below
/// still fire but no upload happens — the crash is swallowed locally.
/// The card shows the live `isCrashlyticsCollectionEnabled` state so
/// the disabled-no-uploads case is obvious before you trigger anything.
///
/// Verification flow:
///   1. flutter run --dart-define=FORCE_CRASHLYTICS=true
///   2. Confirm card says "Collection: enabled" in green.
///   3. Tap "Non-fatal" → uploads immediately, appears under non-fatals
///      tab in Firebase Console → Crashlytics within a few minutes.
///   4. Tap "Force crash" — app dies. Relaunch app. Crashlytics flushes
///      the pending fatal on next start. Fatals tab in console.
///   5. If a fatal seems stuck, tap "Send unsent" to flush manually.
class _CrashTestCard extends StatefulWidget {
  const _CrashTestCard();

  @override
  State<_CrashTestCard> createState() => _CrashTestCardState();
}

class _CrashTestCardState extends State<_CrashTestCard> {
  bool? _collectionEnabled;

  @override
  void initState() {
    super.initState();
    _refreshCollectionState();
  }

  Future<void> _refreshCollectionState() async {
    bool? enabled;
    try {
      enabled = FirebaseCrashlytics.instance.isCrashlyticsCollectionEnabled;
    } catch (_) {
      // FirebaseCrashlytics not initialised (e.g. widget test without
      // Firebase.initializeApp). Leave the state unknown; the card will
      // render a placeholder.
      enabled = null;
    }
    if (!mounted) return;
    setState(() => _collectionEnabled = enabled);
  }

  void _forceFatalCrash() {
    FirebaseCrashlytics.instance.crash();
  }

  void _recordNonFatal() {
    FirebaseCrashlytics.instance.recordError(
      Exception('Test non-fatal error from DroneAid login screen'),
      StackTrace.current,
      reason: 'manual crash-test card',
      fatal: false,
    );
  }

  Future<void> _sendUnsent() async {
    final messenger = ScaffoldMessenger.of(context);
    try {
      await FirebaseCrashlytics.instance.sendUnsentReports();
      if (!mounted) return;
      messenger.showSnackBar(
        const SnackBar(content: Text('Asked Crashlytics to flush.')),
      );
    } catch (e) {
      if (!mounted) return;
      messenger.showSnackBar(SnackBar(content: Text('Flush failed: $e')));
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final enabled = _collectionEnabled;
    final statusLine = enabled == null
        ? const _StatusLine(
            label: 'Collection: …',
            color: Colors.grey,
            icon: Icons.hourglass_empty,
          )
        : enabled
            ? _StatusLine(
                label: 'Collection: enabled',
                color: Colors.green.shade700,
                icon: Icons.check_circle_outline,
              )
            : _StatusLine(
                label: 'Collection: disabled',
                color: theme.colorScheme.error,
                icon: Icons.error_outline,
              );
    return Card(
      margin: EdgeInsets.zero,
      child: Padding(
        padding: const EdgeInsets.all(12),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Crashlytics test',
              style: TextStyle(fontWeight: FontWeight.bold),
            ),
            const SizedBox(height: 6),
            statusLine,
            const SizedBox(height: 6),
            if (enabled == false)
              Text(
                'Uploads disabled in debug. Restart with '
                '--dart-define=FORCE_CRASHLYTICS=true (or run --release).',
                style: TextStyle(
                  fontSize: 12,
                  color: theme.colorScheme.error,
                ),
              )
            else
              const Text(
                'Fatal crash uploads on the NEXT app launch. Non-fatal '
                'uploads immediately. Console can take 2–5 min.',
                style: TextStyle(fontSize: 12),
              ),
            const SizedBox(height: 8),
            Row(
              children: [
                Expanded(
                  child: OutlinedButton.icon(
                    key: const Key('crashlytics-non-fatal'),
                    onPressed: () {
                      _recordNonFatal();
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(
                          content:
                              Text('Non-fatal recorded. Check Crashlytics.'),
                        ),
                      );
                    },
                    icon: const Icon(Icons.warning_amber_outlined),
                    label: const Text('Non-fatal'),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: FilledButton.icon(
                    key: const Key('crashlytics-force-crash'),
                    style: FilledButton.styleFrom(
                      backgroundColor: Colors.red,
                    ),
                    onPressed: _forceFatalCrash,
                    icon: const Icon(Icons.dangerous_outlined),
                    label: const Text('Force crash'),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 6),
            OutlinedButton.icon(
              key: const Key('crashlytics-send-unsent'),
              onPressed: _sendUnsent,
              icon: const Icon(Icons.cloud_upload_outlined),
              label: const Text('Send unsent reports'),
            ),
          ],
        ),
      ),
    );
  }
}

class _StatusLine extends StatelessWidget {
  const _StatusLine({
    required this.label,
    required this.color,
    required this.icon,
  });

  final String label;
  final Color color;
  final IconData icon;

  @override
  Widget build(BuildContext context) {
    return Row(
      children: [
        Icon(icon, size: 14, color: color),
        const SizedBox(width: 6),
        Text(
          label,
          style: TextStyle(
            fontSize: 12,
            fontWeight: FontWeight.w600,
            color: color,
          ),
        ),
      ],
    );
  }
}

// P-U-07 History — terminal-state requests for the signed-in user.
// Spec: docs/09-page-flow-design.md §5 P-U-07.
//
// Reuses myRequestsProvider + catalogNamesProvider + bucketFor from P-U-04
// (request/app_request.dart, request/queue_provider.dart) so both pages
// share a single Firestore stream subscription and one source of truth for
// status bucketing.

import 'package:cloud_functions/cloud_functions.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../core/firebase_errors.dart';
import '../../core/widgets/error_retry.dart';
import '../../core/widgets/loading_placeholder.dart';
import '../../core/widgets/status_chip.dart';
import '../reports/report.dart';
import '../reports/report_dialog.dart';
import '../reports/reports_providers.dart';
import 'request/app_request.dart';
import 'request/queue_provider.dart';

const _functionsRegion = 'asia-southeast1';

/// Request statuses where a Report may be filed (mirrors backend gate
/// in functions/src/callable/reportDeliveryIssue.ts).
const _reportFilableStatuses = {'delivered', 'confirmed', 'failed'};

/// Pure helper — buckets terminal-state requests by their createdAt date,
/// newest day first. Days themselves preserve the input order (which is
/// already createdAt-desc per `myRequestsProvider`), so the per-day rows
/// stay newest-first.
@visibleForTesting
List<MapEntry<DateTime, List<AppRequest>>> groupByDay(List<AppRequest> items) {
  final groups = <DateTime, List<AppRequest>>{};
  for (final r in items) {
    final ts = r.createdAt;
    if (ts == null) continue;
    final day = DateTime(ts.year, ts.month, ts.day);
    (groups[day] ??= <AppRequest>[]).add(r);
  }
  final entries = groups.entries.toList()
    ..sort((a, b) => b.key.compareTo(a.key));
  return entries;
}

/// Pure helper — "Mon, Jun 4" style label. Locale-naive on purpose to keep
/// tests deterministic; intl can layer on later without breaking callers.
@visibleForTesting
String formatDayHeader(DateTime day) {
  const months = [
    'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
  ];
  const weekdays = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  return '${weekdays[day.weekday - 1]}, ${months[day.month - 1]} ${day.day}';
}

class HistoryPage extends ConsumerWidget {
  const HistoryPage({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final async = ref.watch(myRequestsProvider);
    final namesAsync = ref.watch(catalogNamesProvider);

    return Scaffold(
      body: async.when(
        loading: () => const LoadingPlaceholder(label: 'Loading history…'),
        error: (e, _) => ErrorRetry(
          message: 'Failed to load: $e',
          onRetry: () => ref.invalidate(myRequestsProvider),
        ),
        data: (all) {
          final history = all
              .where((r) => r.bucket == QueueBucket.hidden)
              .toList(growable: false);
          final names = namesAsync.valueOrNull ?? const <String, String>{};

          if (history.isEmpty) {
            return RefreshIndicator(
              onRefresh: () async => ref.invalidate(myRequestsProvider),
              child: ListView(
                physics: const AlwaysScrollableScrollPhysics(),
                children: const [
                  SizedBox(height: 96),
                  _EmptyState(),
                ],
              ),
            );
          }

          final grouped = groupByDay(history);
          return RefreshIndicator(
            onRefresh: () async => ref.invalidate(myRequestsProvider),
            child: ListView.builder(
              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
              itemCount: grouped.length,
              itemBuilder: (_, i) {
                final entry = grouped[i];
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Padding(
                      padding: const EdgeInsets.fromLTRB(4, 12, 4, 4),
                      child: Text(
                        formatDayHeader(entry.key),
                        style: Theme.of(context).textTheme.titleSmall,
                      ),
                    ),
                    for (final r in entry.value)
                      _HistoryRow(request: r, catalogNames: names),
                  ],
                );
              },
            ),
          );
        },
      ),
    );
  }
}

class _EmptyState extends StatelessWidget {
  const _EmptyState();

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Center(
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 32),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              Icons.history,
              size: 64,
              color: theme.colorScheme.outline,
            ),
            const SizedBox(height: 12),
            Text(
              'No past deliveries yet',
              style: theme.textTheme.titleMedium,
              textAlign: TextAlign.center,
            ),
            const SizedBox(height: 4),
            Text(
              'Completed, cancelled, and rejected requests show up here.',
              style: theme.textTheme.bodySmall,
              textAlign: TextAlign.center,
            ),
          ],
        ),
      ),
    );
  }
}

class _HistoryRow extends StatelessWidget {
  const _HistoryRow({required this.request, required this.catalogNames});

  final AppRequest request;
  final Map<String, String> catalogNames;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final summary = formatItemSummary(request.items, catalogNames);
    final time = relativeTime(request.createdAt);

    return Card(
      margin: const EdgeInsets.symmetric(vertical: 4),
      child: InkWell(
        key: Key('history-row-${request.id}'),
        onTap: () => _showDetailSheet(context, request, summary),
        child: Padding(
          padding: const EdgeInsets.all(12),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Expanded(
                    child: Text(
                      '#${request.id}',
                      style: theme.textTheme.titleSmall,
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                  StatusChip(status: request.status),
                ],
              ),
              const SizedBox(height: 4),
              Text(summary, style: theme.textTheme.bodyLarge),
              const SizedBox(height: 4),
              Wrap(
                spacing: 12,
                runSpacing: 4,
                children: [
                  Text(
                    '${request.totalWeightKg.toStringAsFixed(1)} kg',
                    style: theme.textTheme.bodySmall,
                  ),
                  Text(time, style: theme.textTheme.bodySmall),
                  if (request.currentFlightId != null)
                    Text(
                      'Flight ${request.currentFlightId}',
                      style: theme.textTheme.bodySmall,
                      overflow: TextOverflow.ellipsis,
                    ),
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }
}

Future<void> _showDetailSheet(
  BuildContext context,
  AppRequest request,
  String summary,
) {
  return showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    showDragHandle: true,
    builder: (ctx) => _DetailSheet(request: request, summary: summary),
  );
}

class _DetailSheet extends ConsumerStatefulWidget {
  const _DetailSheet({required this.request, required this.summary});
  final AppRequest request;
  final String summary;

  @override
  ConsumerState<_DetailSheet> createState() => _DetailSheetState();
}

class _DetailSheetState extends ConsumerState<_DetailSheet> {
  bool _filing = false;

  Future<void> _fileReport() async {
    final message = await showReportDialog(context);
    if (message == null || !mounted) return;
    final messenger = ScaffoldMessenger.of(context);
    setState(() => _filing = true);
    try {
      await FirebaseFunctions.instanceFor(region: _functionsRegion)
          .httpsCallable('reportDeliveryIssue')
          .call<Map<String, dynamic>>({
        'reqId': widget.request.id,
        'message': message,
      });
      if (!mounted) return;
      messenger.showSnackBar(
        const SnackBar(content: Text('Report sent. Coordinator notified.')),
      );
    } catch (e) {
      if (!mounted) return;
      messenger.showSnackBar(
        SnackBar(
          content: Text('Could not send report: ${describeFunctionsError(e)}'),
        ),
      );
    } finally {
      if (mounted) setState(() => _filing = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final request = widget.request;
    final reportsAsync = ref.watch(requestReportsProvider(request.id));
    final hasOpenReport = reportsAsync.maybeWhen(
      data: (rs) => rs.any((r) => r.status == ReportStatus.open),
      orElse: () => false,
    );
    final canReport = _reportFilableStatuses.contains(request.status) &&
        !hasOpenReport;

    return SafeArea(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(20, 0, 20, 24),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Expanded(
                  child: Text(
                    '#${request.id}',
                    style: theme.textTheme.titleMedium,
                  ),
                ),
                StatusChip(status: request.status),
              ],
            ),
            const SizedBox(height: 12),
            _DetailRow(label: 'Items', value: widget.summary),
            _DetailRow(
              label: 'Total weight',
              value: '${request.totalWeightKg.toStringAsFixed(1)} kg',
            ),
            _DetailRow(
              label: 'Submitted',
              value: request.createdAt?.toString() ?? '—',
            ),
            if (request.currentFlightId != null)
              _DetailRow(
                label: 'Last flight',
                value: request.currentFlightId!,
              ),
            reportsAsync.maybeWhen(
              data: (reports) => reports.isEmpty
                  ? const SizedBox.shrink()
                  : _UserReportsList(reports: reports),
              orElse: () => const SizedBox.shrink(),
            ),
            if (canReport) ...[
              const SizedBox(height: 16),
              OutlinedButton.icon(
                key: const Key('history-report-button'),
                onPressed: _filing ? null : _fileReport,
                icon: const Icon(Icons.report_outlined),
                label: const Text('Report a problem'),
              ),
            ],
          ],
        ),
      ),
    );
  }
}

class _UserReportsList extends StatelessWidget {
  const _UserReportsList({required this.reports});
  final List<Report> reports;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Padding(
      padding: const EdgeInsets.only(top: 16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Text(
            'Reports',
            style: theme.textTheme.titleSmall,
          ),
          const SizedBox(height: 6),
          for (final r in reports)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 4),
              child: _UserReportTile(report: r),
            ),
        ],
      ),
    );
  }
}

class _UserReportTile extends StatelessWidget {
  const _UserReportTile({required this.report});
  final Report report;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final color = switch (report.status) {
      ReportStatus.open => theme.colorScheme.errorContainer,
      ReportStatus.resolved => theme.colorScheme.primaryContainer,
      ReportStatus.dismissed => theme.colorScheme.surfaceContainerHighest,
    };
    final onColor = switch (report.status) {
      ReportStatus.open => theme.colorScheme.onErrorContainer,
      ReportStatus.resolved => theme.colorScheme.onPrimaryContainer,
      ReportStatus.dismissed => theme.colorScheme.onSurfaceVariant,
    };
    return Container(
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: color,
        borderRadius: BorderRadius.circular(8),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Text(
                report.status.wire,
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w700,
                  color: onColor,
                ),
              ),
              const Spacer(),
              if (report.resolution != null)
                Text(
                  report.resolution!.label,
                  style: TextStyle(fontSize: 11, color: onColor),
                ),
            ],
          ),
          const SizedBox(height: 4),
          Text(
            report.message,
            style: TextStyle(fontSize: 13, color: onColor),
          ),
          if (report.resolutionNote != null) ...[
            const SizedBox(height: 4),
            Text(
              'Admin: ${report.resolutionNote}',
              style: TextStyle(
                fontSize: 12,
                fontStyle: FontStyle.italic,
                color: onColor,
              ),
            ),
          ],
        ],
      ),
    );
  }
}

class _DetailRow extends StatelessWidget {
  const _DetailRow({required this.label, required this.value});
  final String label;
