1	// P-U-08 Notifications — in-app inbox.
2	// Spec: docs/09-page-flow-design.md §5 P-U-08.
3	
4	import 'package:cloud_firestore/cloud_firestore.dart';
5	import 'package:firebase_auth/firebase_auth.dart';
6	import 'package:flutter/material.dart';
7	import 'package:flutter_riverpod/flutter_riverpod.dart';
8	import 'package:go_router/go_router.dart';
9	
10	import '../../core/firebase_errors.dart';
11	import '../../core/widgets/empty_state.dart';
12	import '../../core/widgets/loading_placeholder.dart';
13	import 'notifications/notifications_provider.dart';
14	import 'request/app_request.dart' show relativeTime;
15	
16	/// One-shot existence check for a deepLink destination, so a stale
17	/// notification doesn't navigate the user to a "not found" page.
18	/// Returns true for routes that don't depend on a per-resource doc.
19	Future<bool> _destinationExists(String deepLink) async {
20	  final reqMatch =
21	      RegExp(r'^/(?:user/confirm|admin/requests)/([^/]+)$').firstMatch(deepLink);
22	  if (reqMatch != null) {
23	    final snap = await FirebaseFirestore.instance
24	        .doc('requests/${reqMatch.group(1)}')
25	        .get();
26	    return snap.exists;
27	  }
28	  final flightMatch =
29	      RegExp(r'^/(?:user/tracking|admin/drones)/([^/]+)$').firstMatch(deepLink);
30	  if (flightMatch != null) {
31	    final coll = deepLink.startsWith('/user/tracking') ? 'flights' : 'drones';
32	    final snap = await FirebaseFirestore.instance
33	        .doc('$coll/${flightMatch.group(1)}')
34	        .get();
35	    return snap.exists;
36	  }
37	  // List/index routes (e.g. /admin/reports, /user/history) are always valid.
38	  return true;
39	}
40	
41	class NotificationsPage extends ConsumerWidget {
42	  const NotificationsPage({super.key});
43	
44	  Future<void> _markRead(String uid, String nid) async {
45	    await FirebaseFirestore.instance
46	        .doc('users/$uid/notifications/$nid')
47	        .update({'readAt': FieldValue.serverTimestamp()});
48	  }
49	
50	  Future<void> _markAllRead(
51	    BuildContext context,
52	    String uid,
53	    List<AppNotification> notifications,
54	  ) async {
55	    final messenger = ScaffoldMessenger.of(context);
56	    final unread = notifications.where((n) => n.isUnread).toList();
57	    if (unread.isEmpty) return;
58	    final batch = FirebaseFirestore.instance.batch();
59	    for (final n in unread) {
60	      batch.update(
61	        FirebaseFirestore.instance.doc('users/$uid/notifications/${n.id}'),
62	        {'readAt': FieldValue.serverTimestamp()},
63	      );
64	    }
65	    try {
66	      await batch.commit();
67	      if (!context.mounted) return;
68	      messenger.showSnackBar(
69	        SnackBar(content: Text('Marked ${unread.length} as read.')),
70	      );
71	    } catch (e) {
72	      if (!context.mounted) return;
73	      messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
74	    }
75	  }
76	
77	  @override
78	  Widget build(BuildContext context, WidgetRef ref) {
79	    final async = ref.watch(notificationsProvider);
80	    final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
81	
82	    return Scaffold(
83	      body: async.when(
84	        loading: () => const LoadingPlaceholder(label: 'Loading notifications…'),
85	        error: (e, _) => Center(child: Text('Failed to load notifications: ${describeFunctionsError(e)}')),
86	        data: (notifications) {
87	          if (notifications.isEmpty) {
88	            return const EmptyState(
89	              icon: Icons.notifications_none,
90	              title: 'No notifications yet',
91	              helper: 'Updates about your drone deliveries will show up here.',
92	            );
93	          }
94	          final hasUnread = notifications.any((n) => n.isUnread);
95	          return Column(
96	            children: [
97	              if (hasUnread)
98	                Padding(
99	                  padding: const EdgeInsets.fromLTRB(8, 8, 8, 0),
100	                  child: Align(
101	                    alignment: Alignment.centerRight,
102	                    child: TextButton.icon(
103	                      key: const Key('mark-all-read'),
104	                      onPressed: () =>
105	                          _markAllRead(context, uid, notifications),
106	                      icon: const Icon(Icons.done_all),
107	                      label: const Text('Mark all as read'),
108	                    ),
109	                  ),
110	                ),
111	              Expanded(
112	                child: ListView.separated(
113	                  itemCount: notifications.length,
114	                  separatorBuilder: (_, __) => const Divider(height: 1),
115	                  itemBuilder: (context, i) {
116	                    final n = notifications[i];
117	                    return ListTile(
118	                      leading: Icon(
119	                        Icons.notifications,
120	                        color: n.isUnread
121	                            ? Theme.of(context).colorScheme.primary
122	                            : Theme.of(context).colorScheme.outline,
123	                      ),
124	                      title: Text(
125	                        n.title,
126	                        style: TextStyle(
127	                          fontWeight: n.isUnread
128	                              ? FontWeight.bold
129	                              : FontWeight.normal,
130	                        ),
131	                      ),
132	                      subtitle: Column(
133	                        crossAxisAlignment: CrossAxisAlignment.start,
134	                        children: [
135	                          Text(
136	                            n.body,
137	                            maxLines: 2,
138	                            overflow: TextOverflow.ellipsis,
139	                          ),
140	                          Text(
141	                            relativeTime(n.createdAt),
142	                            style: Theme.of(context).textTheme.bodySmall,
143	                          ),
144	                        ],
145	                      ),
146	                      isThreeLine: true,
147	                      onTap: () async {
148	                        final messenger = ScaffoldMessenger.of(context);
149	                        if (n.isUnread) await _markRead(uid, n.id);
150	                        final exists = await _destinationExists(n.deepLink);
151	                        if (!context.mounted) return;
152	                        if (!exists) {
153	                          messenger.showSnackBar(
154	                            const SnackBar(
155	                              content: Text(
156	                                'This notification is no longer available.',
157	                              ),
158	                            ),
159	                          );
160	                          return;
161	                        }
162	                        context.go(n.deepLink);
163	                      },
164	                    );
165	                  },
166	                ),
167	              ),
168	            ],
169	          );
170	        },
171	      ),
172	    );
173	  }
174	}
