1	// Scheduled tick: every 60 s, advance every active flight.
2	// Spec: §8 sim engine, §10 tickFlights, flow F-19/F-20.
3	
4	import { onSchedule } from "firebase-functions/v2/scheduler";
5	import { db, Timestamp } from "../lib/admin";
6	import { type WeatherState } from "../lib/weather";
7	import { deliveringHoldElapsed, rollAbort, snapshot } from "../lib/sim";
8	
9	const ACTIVE_STATUSES = ["enroute", "delivering", "returning"] as const;
10	
11	/// Battery recharged per tick for drones held in `maintenance`. Picked
12	/// so a fully-drained drone takes ~5 ticks (5 minutes at the 1-minute
13	/// schedule) to climb back to 100%. See
14	/// docs/adr/0005-recall-and-storm-evacuation.md.
15	const MAINTENANCE_CHARGE_PER_TICK = 20;
16	
17	/// A `returning` flight that doesn't complete within this real-time
18	/// window is force-aborted and the drone is sent to `maintenance` for
19	/// human inspection. Defensive — under nominal sim physics a return
20	/// trip finishes well within this budget.
21	const RETURNING_TIMEOUT_MS = 30 * 60 * 1000;
22	
23	/// Advances every active flight one tick. Pure body — reusable from the
24	/// scheduled wrapper below and from `devTickFlights` (dev-only callable for
25	/// the emulator, where scheduled triggers do not fire).
26	///
27	/// Returns `{ count }` so callers can surface "ticked N flights" to the UI.
28	export async function tickAllFlights(nowMs: number = Date.now()): Promise<{ count: number }> {
29	  const weatherSnap = await db.doc("weather/current").get();
30	  const weather = ((weatherSnap.data()?.state as WeatherState) ?? "clear");
31	
32	  const flightsSnap = await db
33	    .collection("flights")
34	    .where("status", "in", ACTIVE_STATUSES as unknown as string[])
35	    .get();
36	
37	  for (const doc of flightsSnap.docs) {
38	    const f = doc.data();
39	    const flightState = {
40	      origin: f.origin,
41	      destination: f.destination,
42	      takeoffAt: (f.takeoffAt as FirebaseFirestore.Timestamp).toMillis(),
43	      speedKmh: f.speedKmh as number,
44	      weatherModifierAtTakeoff: f.weatherModifierAtTakeoff as number,
45	      batteryAtTakeoff: f.batteryAtTakeoff as number,
46	    };
47	    const snap = snapshot(flightState, nowMs, weather);
48	
49	    const status = f.status as (typeof ACTIVE_STATUSES)[number];
50	    const requestId = f.requestId as string;
51	    const droneId = f.droneId as string;
52	
53	    // ── Enroute: roll failure dice, otherwise advance toward delivering ────
54	    if (status === "enroute") {
55	      const abort = rollAbort({ weather, battery: snap.battery });
56	      if (abort) {
57	        await failFlight(doc.id, requestId, droneId, abort, snap.battery);
58	        continue;
59	      }
60	      if (snap.progress >= 1.0) {
61	        await doc.ref.update({
62	          status: "delivering",
63	          deliveringStartedAt: Timestamp.fromMillis(nowMs),
64	        });
65	        continue;
66	      }
67	      continue; // still in flight, no DB write needed
68	    }
69	
70	    // ── Delivering: hold 60 s then complete ──────────────────────────────
71	    if (status === "delivering") {
72	      const startMs = (f.deliveringStartedAt as FirebaseFirestore.Timestamp | undefined)
73	        ?.toMillis() ?? nowMs;
