  Widget build(BuildContext context) {
    final location = GoRouterState.of(context).matchedLocation;
    final primaryIndex = _primaryIndexFor(location);
    if (_controller.index != primaryIndex &&
        !_controller.indexIsChanging) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        _syncing = true;
        _controller.animateTo(primaryIndex);
      });
    }

    final themeMode = ref.watch(themeModeProvider);
    final isDark = themeMode == ThemeMode.dark ||
        (themeMode == ThemeMode.system &&
            MediaQuery.platformBrightnessOf(context) == Brightness.dark);

    return Scaffold(
      appBar: AppBar(
        titleSpacing: AppSpacing.md,
        title: const _AdminTitle(),
        actions: [
          AppBarAction(
            tooltip: isDark ? 'Light mode' : 'Dark mode',
            onTap: () => ref.read(themeModeProvider.notifier).toggle(),
            child: Icon(
              isDark ? Icons.dark_mode_outlined : Icons.wb_sunny_outlined,
              size: 18,
            ),
          ),
          AppBarAction(
            tooltip: 'Weather',
            onTap: () => context.go('/admin/weather'),
            child: const WeatherChipGlyph(),
          ),
          AppBarAction(
            tooltip: 'Notifications',
            onTap: () => context.go('/admin/notifications'),
            child: const NotificationBellGlyph(),
          ),
          const SizedBox(width: AppSpacing.sm),
        ],
        bottom: PreferredSize(
          preferredSize: const Size.fromHeight(46),
          child: TabBar(
            controller: _controller,
            isScrollable: false,
            tabs: [
              for (final t in _tabs)
                Tab(
                  height: 46,
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(t.icon, size: 16),
                      const SizedBox(width: 6),
                      Text(t.label),
                    ],
                  ),
                ),
              const Tab(
                height: 46,
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(Icons.more_horiz, size: 16),
                    SizedBox(width: 6),
                    Text('More'),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
      body: widget.child,
    );
  }

  Future<void> _showMoreSheet() async {
    await showModalBottomSheet<void>(
      context: context,
      showDragHandle: true,
      builder: (ctx) {
        return SafeArea(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              ListTile(
                leading: const Icon(Icons.report_outlined),
                title: const Text('Reports'),
                onTap: () {
                  Navigator.of(ctx).pop();
                  context.go('/admin/reports');
                },
              ),
              ListTile(
                leading: const Icon(Icons.cloud_outlined),
                title: const Text('Weather'),
                onTap: () {
                  Navigator.of(ctx).pop();
                  context.go('/admin/weather');
                },
              ),
              ListTile(
                leading: const Icon(Icons.inventory_2_outlined),
                title: const Text('Inventory'),
                onTap: () {
                  Navigator.of(ctx).pop();
                  context.go('/admin/inventory');
                },
              ),
              ListTile(
                leading: const Icon(Icons.person_outline),
                title: const Text('Profile'),
                onTap: () {
                  Navigator.of(ctx).pop();
                  context.go('/admin/profile');
                },
              ),
              const SizedBox(height: AppSpacing.sm),
            ],
          ),
        );
      },
    );
  }
}

class _AdminTitle extends StatelessWidget {
  const _AdminTitle();

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: const [
        BrandMark(),
        SizedBox(width: AppSpacing.sm),
        RolePill(role: 'Admin', dense: true),
      ],
    );
  }
}

class _AdminTabSpec {
  const _AdminTabSpec({
    required this.route,
    required this.label,
    required this.icon,
  });
  final String route;
  final String label;
  final IconData icon;
}

