1	// Dev-only callable that advances every active flight by one tick.
2	//
3	// Why this exists: the `tickFlights` scheduled function (every 1 min) does
4	// not fire under the Firebase emulator because there is no pub/sub emulator.
5	// Without it, flight statuses never transition past `enroute` and the demo
6	// gets stuck. This callable wraps the same `tickAllFlights` body so an admin
7	// can hit "Tick now" on the Control page during demos.
8	//
9	// Hard-gated to emulator-only via FUNCTIONS_EMULATOR (set by the Firebase
10	// emulator runtime). Per ADR-0002 we do not deploy to prod, but defence in
11	// depth — this must never run against a real Firestore.
12	
13	import { HttpsError, onCall } from "firebase-functions/v2/https";
14	import { requireAdmin } from "../lib/roles";
15	import { tickAllFlights } from "../scheduled/tickFlights";
