                            strokeWidth: 2,
                            color: Colors.white,
                          ),
                        )
                      : const Text('Yes, confirm'),
                ),
                const SizedBox(height: 12),
                OutlinedButton(
                  onPressed: _loading ? null : _reportProblem,
                  child: const Text("Something's wrong — report"),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}

