    padding: const EdgeInsets.fromLTRB(
      AppSpacing.md, 0, AppSpacing.md, AppSpacing.sm + 2,
    ),
    child: Card(
      child: InkWell(
        key: Key('queue-row-${request.id}'),
        onTap: (isInFlight || isDelivered) ? onTap : null,
        borderRadius: BorderRadius.circular(AppRadii.card),
